import{EXESNOHS_CONFIG as d}from"./config.min.js";const x=n=>n*n*(3-2*n),p=n=>1-(1-n)*(1-n);export function contactFraction(n){const t=d.pose.takedown,c=Math.max(0,n-t.close),e=c>0?(n-t.contact)/c:0;if(!(e>0))return t.contactAt.min;if(e>=1)return t.contactAt.max;const o=1-Math.sqrt(1-e);return Math.min(t.contactAt.max,Math.max(t.contactAt.min,o))}export function takedownLength(n=1/0){const t=d.pose.takedown,c=Number.isFinite(n)?contactFraction(n):t.contactAt.max;return Math.max(t.dive,c*t.dive+t.fall)+t.settle}export function takedownAt(n,t,c){const e=d.pose.takedown,o=c.x-t.x,a=c.z-t.z,s=Math.hypot(o,a)||1e-6,h=o/s,l=a/s,u=Math.max(0,s-e.close),i=Math.min(1,Math.max(0,n/e.dive)),f=contactFraction(s)*e.dive,r=Math.min(1,Math.max(0,(n-f)/e.fall)),z=Math.sin(Math.PI*i)*e.leap,k=Math.max(0,1-r*1.6),m=h*e.driven*x(r),M=l*e.driven*x(r);return{tackler:{x:h*u*p(i)+m*e.carry,y:z*k,z:l*u*p(i)+M*e.carry,lean:e.tacklerLean*x(i)},carrier:{x:m,z:M,lean:e.carrierLean*x(r)},contact:n>=f?1:0}}export function takedownRest(n,t){const c=Math.hypot(t.x-n.x,t.z-n.z),e=takedownLength(c),o=takedownAt(e,n,t);return{tackler:{x:n.x+o.tackler.x,z:n.z+o.tackler.z},carrier:{x:t.x+o.carrier.x,z:t.z+o.carrier.z},length:e}}export function tacklerFor(n,t){if(!t)return"";let c="",e=1/0;for(const o of n){if(o===t||o.settings.benched||o.settings.position==="ball"||o.settings.team===t.settings.team)continue;const a=Math.hypot(o.coords.x-t.coords.x,o.coords.y-t.coords.y);a<e&&(e=a,c=o.settings.position)}return c}
